-- GEN bg3gen.core.toggle (GENERATED by python -m bg3gen CC_Ladder_SE <yaml> from the pak yaml's `toggles:`; never edit by
-- hand, rebuild). `!<command> off | on` on the server console; default ON; one dated `toggle` log line per switch.
local PAK, WHO = "CC_Ladder_SE", "host"
local CMDS = {
  ["cc"] = "the CC ladder (on = the stats-file ladder, off = vanilla DOS3 CC at once, no restart; combat only either way)",
}
BG3GEN_Toggle = {}
local T, ON, FN, LOG = BG3GEN_Toggle, {}, {}, nil
for c in pairs(CMDS) do ON[c], FN[c] = true, {} end  -- DEFAULT ON (every load)
local function say(s) pcall(Ext.Utils.Print, "[" .. PAK .. "] " .. s) end
function T.is_on(c) return ON[c] ~= false end
function T.on_change(c, f) if FN[c] then FN[c][#FN[c] + 1] = f end end
function T.log_with(f) LOG = f end  -- the pak's own JSON-lines writer (one logger per file: SaveFile replaces the file)
function T.set(c, on, who)
  if not CMDS[c] then return false end
  ON[c] = on and true or false
  local ok, ep = pcall(function() return Ext.Timer.ClockEpoch() end)
  local line = {cmd = c, state = on and "on" or "off", who = who or "?", epoch = ok and ep or nil, what = CMDS[c]}
  say("!" .. c .. " " .. line.state .. " (" .. line.who .. ")")
  if LOG then pcall(LOG, "toggle", line) end
  for _, f in ipairs(FN[c]) do
    local okf, err = pcall(f, ON[c], line.who)
    if not okf then say("!" .. c .. " " .. line.state .. ": " .. tostring(err)) end
  end
  return true
end
for c, what in pairs(CMDS) do
  pcall(Ext.RegisterConsoleCommand, c, function(cmd, arg)
    local a = string.lower(tostring(arg or ""))
    if a == "off" or a == "on" then T.set(c, a == "on", WHO)
    else say("!" .. c .. " off | !" .. c .. " on (now " .. (ON[c] and "on" or "off") .. "): " .. what) end
  end)
end
